// Offline component audition, not a proposed plugin engine.
#include "../tests/ControlFixtures.h"
static std::vector<float> clean(const std::vector<float>&a,int mode){std::vector<float>b;double phase=1;float held=0,lowError=0;const float k=1-std::exp(-6.2831853f*140/sr);for(float x:a){if(phase>=1){phase-=std::floor(phase);held=mode==2?x:std::round(x*128)/128;}phase+=(mode==1?sr:3000.)/sr;float error=held-x;lowError+=k*(error-lowError);float y=x+error-lowError;require(std::isfinite(y)&&std::abs(y)<1,"Invalid audition");b.push_back(y);}return b;}
static void add(std::vector<float>&out,const std::vector<float>&in){auto a=match(in);out.insert(out.end(),a.begin(),a.end());out.resize(out.size()+sr/4,0);}
int main(int argc,char**argv){std::filesystem::path dir(argv[1]);std::filesystem::create_directories(dir);std::array<std::vector<float>,3> sources{bass(0,sr*2),bass(2,sr*2),bass(1,sr*2)};for(int mode=0;mode<4;++mode){std::vector<float>out;for(auto&a:sources)add(out,mode?clean(a,mode):a);wav(dir/(std::to_string(mode)+std::string(mode==0?"-dry.wav":mode==1?"-8bit-only.wav":mode==2?"-hold-only.wav":"-8bit-and-hold.wav")),out);}auto silence=std::vector<float>(sr,0);for(int mode=1;mode<4;++mode)require(clean(silence,mode)==silence,"Nonzero silence");std::cout<<"Four synthetic component auditions; finite output and silence passed.\n";}
